#pragma once
/*
  SurahNames.h
  ------------------------------------------------------------
  The 114 surah names in Arabic, as small one-bit images (no font
  and no text shaping is needed on the watch). Each name was shaped
  and rendered offline with the Lateef Regular font (SIL Open Font
  License 1.1, (c) SIL International) at 20 px, then reduced to 1 bit.
  Credit the font in your README if you redistribute this file.

  Each name is SURAH_NAME_ROWS rows tall; row 0 is the top, the text
  baseline is at row SURAH_NAME_BASELINE. A row is a uint64_t: bit
  (63 - column) is set for an ink pixel. SURAH_NAME_W[i] is the width
  in pixels of surah i + 1.
*/

