// Draws the Arabic name of `surah` (1..114), horizontally centered on
// cx, with its top row at y = top.
inline void drawSurahName(Adafruit_GFX &d, uint8_t surah, int16_t cx,
                          int16_t top) {
  if (surah < 1 || surah > 114) return;
  const uint8_t idx = surah - 1;
  const int16_t w = SURAH_NAME_W[idx];
  const int16_t x0 = cx - w / 2;
  for (int16_t row = 0; row < SURAH_NAME_ROWS; row++) {
    const uint64_t bits = SURAH_NAME_BITS[idx][row];
    if (!bits) continue;
    for (int16_t col = 0; col < w; col++) {
      if (bits & (1ULL << (63 - col))) {
        d.drawPixel(x0 + col, top + row, qwInk());
      }
    }
  }
}